'use strict';(function(root){const labels={weapon:'무기',armor:'방어구',accessory:'장신구',relic:'유물'},paths={weapon:'M9 31 29 11 33 3 25 7 5 27M9 23l8 8M5 27l-3 7 7-3',armor:'m12 5 6 4 6-4 9 7-5 8-4-2v15H12V18l-4 2-5-8Z',accessory:'M12 10 18 3 24 10 18 17ZM12 12a13 13 0 1 0 12 0',relic:'m18 3 13 8v15l-13 8-13-8V11Zm0 7 6 8-6 8-6-8Z'};
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),fmt=n=>Math.floor(n).toLocaleString('ko-KR'),pct=n=>Number(n.toFixed(2)).toLocaleString('ko-KR',{maximumFractionDigits:2});
function icon(slot){return '<svg viewBox="0 0 36 36" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="'+paths[slot]+'"/></svg>';}
function markup(g,slot='weapon',result=null){if(!Object.hasOwn(labels,slot))slot='weapon';const h=g.h,s=g.upgradeSpec(slot),key=h.equip[slot],it=key?g.describe(key):null,ready=!s.max&&h.gold>=s.gold&&h.dust>=s.dust,n=s.level,success=s.success,great=s.greatSuccess||0,normal=s.normalSuccess??success;
const power=g.power(),old=h.slotUpgrades[slot];let next=power,greatPower=power;try{h.slotUpgrades[slot]=Math.min(50,n+1);next=g.power();h.slotUpgrades[slot]=Math.min(50,n+2);greatPower=g.power();}finally{h.slotUpgrades[slot]=old;}
const states={success:['강화 성공','한 단계 더 강해졌어요.'],great:['대성공','한 번에 두 단계 상승!'],failure:['강화 실패','강화 단계는 유지됐어요.'],critical:['대실패','한 단계 내려갔어요.']},r=result?.slot===slot?result:null,verdict=r?states[r.result]:null;
return `<section class="forge ${r?'forge-result result-'+r.result:''}" aria-label="슬롯 강화"><div class="forge-top"><button class="forge-back" data-back-bag="1">← 장비 · 가방</button><span>최대 +50</span></div><div class="forge-intro"><span>THE FORGE</span><h3>더 강해질 시간</h3><p>장비를 바꿔도, 강화는 그대로.</p></div><nav class="forge-slots" aria-label="강화 슬롯">${Object.entries(labels).map(([k,label])=>`<button data-forge-slot="${k}" aria-pressed="${k===slot}" ${k===slot?'class="selected"':''}>${icon(k)}<span>${label}</span><b>+${g.slotLevel(k)}</b></button>`).join('')}</nav><div class="forge-layout"><div class="forge-showcase"><span class="forge-slot-label">${labels[slot]} 슬롯</span><div class="forge-art"><i></i><i></i><i></i><div class="forge-artifact">${it?`<canvas width="150" height="150" data-sheet="${escape(it.sheet)}" data-cell="${it.cell}" data-height="112" aria-label="${escape(it.name)}"></canvas>`:icon(slot)}</div><span class="forge-level">+${n}</span></div><strong class="forge-item-name">${escape(it?.name||labels[slot]+' 슬롯')}</strong><small>${it?escape(it.rarity)+' · 장착 중':'빈 슬롯도 미리 강화할 수 있어요'}</small><div class="forge-step"><span>현재 <b>+${n}</b></span><i>→</i><span>성공 <b>+${Math.min(50,n+1)}</b></span>${great>0?`<em>대성공 +${Math.min(50,n+2)}</em>`:''}</div><div class="forge-verdict" role="status" aria-live="polite">${verdict?`<strong>${verdict[0]}</strong><span>+${r.from} → +${r.to} · ${verdict[1]}</span>`:`<span>${s.max?'최고 단계에 도달했어요.':'성공의 순간을 만들어 보세요.'}</span>`}</div></div><div class="forge-details"><div class="forge-power"><span>성공 시 전투력</span><div><b>${fmt(power)}</b><i>→</i><strong>${fmt(next)}</strong></div><small>${next>power?'▲ +'+fmt(next-power):'장비를 장착하면 강화 효과가 적용돼요'}${great>0&&greatPower>next?' · 대성공 시 +'+fmt(greatPower-power):''}</small></div><div class="forge-odds"><div class="forge-section-title"><h4>강화 확률</h4><span>실제 적용 확률</span></div><div class="forge-chance"><span>성공 확률</span><strong>${pct(success)}<small>%</small></strong></div><div class="forge-probability" aria-label="일반 성공 ${pct(normal)}%, 대성공 ${pct(great)}%, 실패 ${pct(s.failure)}%, 대실패 ${pct(s.critical)}%"><i style="width:${normal}%"></i><i style="width:${great}%"></i><i style="width:${s.failure}%"></i><i style="width:${s.critical}%"></i></div><dl><div><dt><i class="odds-normal"></i>일반 성공 <small>+1강</small></dt><dd>${pct(normal)}%</dd></div><div><dt><i class="odds-great"></i>대성공 <small>+2강</small></dt><dd>${pct(great)}%</dd></div><div><dt><i class="odds-failure"></i>실패 <small>단계 유지</small></dt><dd>${pct(s.failure)}%</dd></div><div><dt><i class="odds-critical"></i>대실패 <small>−1강</small></dt><dd>${pct(s.critical)}%</dd></div></dl></div><div class="forge-materials"><h4>필요 재료</h4><div class="${h.gold<s.gold?'insufficient':''}"><span>골드</span><b>${fmt(s.gold)} <small>/ ${fmt(h.gold)} 보유</small></b></div><div class="${h.dust<s.dust?'insufficient':''}"><span>강화석</span><b>${fmt(s.dust)} <small>/ ${fmt(h.dust)} 보유</small></b></div></div><p class="forge-rules">모든 시도에 재료가 소모돼요.<br>+9 이하는 하락 없음 · +10부터 대실패 시 1단계 하락<br>+49에서는 일반 성공으로 +50에 도달해요.</p></div></div><footer class="forge-footer"><div><strong>${s.max?'강화 완료':ready?'준비됐어요':h.gold<s.gold?'골드가 부족해요':'강화석이 부족해요'}</strong><span>${s.max?'최대 단계 +50':great>0?'대성공은 전체 성공 확률에 포함돼요.':'슬롯에 영구 적용돼요.'}</span></div><button class="forge-submit" data-forge-attempt="${slot}" ${ready?'':'disabled'}>${s.max?'최대 강화':'강화하기'}<span>${s.max?'MAX':'✦'}</span></button></footer></section>`;}
const API={markup,icon};if(typeof module!=='undefined')module.exports=API;root.RPG_FORGE=API;})(typeof window!=='undefined'?window:globalThis);
